-- SQLite: 외래 키 설정은 트랜잭션 시작 전에 이 연결에서 활성화합니다.
PRAGMA foreign_keys=ON;
CREATE TABLE person(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE club(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE membership(person TEXT NOT NULL REFERENCES person(id),
 club TEXT NOT NULL REFERENCES club(id), PRIMARY KEY(person,club));
INSERT INTO person VALUES ('P1'),('P2');
INSERT INTO club VALUES ('C1'),('C2');
INSERT INTO membership VALUES ('P1','C1'),('P1','C2'),('P2','C2');
SELECT person,club FROM membership ORDER BY person,club;
